import React, { useEffect, useState } from 'react';
import Icon from './Icon';
import { getTeacherSummary } from '../services/api';
import type { TeacherSummary } from '../types';

interface AiSummaryProps {
    teacherId: number;
    /** Approved review count; the summary needs at least MIN_REVIEWS. */
    reviewCount: number;
}

const MIN_REVIEWS = 3;

/**
 * Roman Urdu overview of a teacher's reviews, generated by Gemini on the
 * server and cached until a review is approved, edited or removed.
 * Renders nothing when there is no summary to show.
 */
const AiSummary: React.FC<AiSummaryProps> = ({ teacherId, reviewCount }) => {
    const [summary, setSummary] = useState<TeacherSummary | null>(null);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (reviewCount < MIN_REVIEWS) {
            setSummary(null);
            return undefined;
        }
        let cancelled = false;
        setLoading(true);
        setSummary(null);
        getTeacherSummary(teacherId)
            .then((res) => { if (!cancelled) setSummary(res.data as TeacherSummary); })
            .catch(() => { if (!cancelled) setSummary(null); })
            .finally(() => { if (!cancelled) setLoading(false); });
        return () => { cancelled = true; };
    }, [teacherId, reviewCount]);

    if (reviewCount < MIN_REVIEWS) return null;

    if (loading) {
        return (
            <section className="ai-summary ai-summary-loading" aria-busy="true" aria-label="AI summary loading">
                <div className="ai-summary-head">
                    <Icon name="sparkles" size={16} />
                    <span>AI summary</span>
                </div>
                <div className="ai-summary-skeleton" />
                <div className="ai-summary-skeleton ai-summary-skeleton-short" />
            </section>
        );
    }

    if (!summary || !summary.available) return null;

    return (
        <section className="ai-summary" aria-label="AI summary of student reviews">
            <div className="ai-summary-head">
                <span className="ai-summary-icon" aria-hidden="true"><Icon name="sparkles" size={15} /></span>
                <span className="ai-summary-title">AI summary</span>
                <span className="ai-summary-badge">{summary.review_count} reviews se</span>
            </div>
            {summary.overview && <p className="ai-summary-overview">{summary.overview}</p>}
            {(summary.pros.length > 0 || summary.cons.length > 0) && (
                <div className="ai-summary-lists">
                    {summary.pros.length > 0 && (
                        <div className="ai-summary-box ai-summary-box-pro">
                            <p className="ai-summary-label ai-summary-label-pro">
                                <Icon name="thumbs-up" size={14} /> Students ko pasand
                            </p>
                            <ul>
                                {summary.pros.map((p, i) => <li key={i}>{p}</li>)}
                            </ul>
                        </div>
                    )}
                    {summary.cons.length > 0 && (
                        <div className="ai-summary-box ai-summary-box-con">
                            <p className="ai-summary-label ai-summary-label-con">
                                <Icon name="alert-triangle" size={14} /> Mushkilaat
                            </p>
                            <ul>
                                {summary.cons.map((c, i) => <li key={i}>{c}</li>)}
                            </ul>
                        </div>
                    )}
                </div>
            )}
            <p className="ai-summary-note">
                <Icon name="info" size={13} />
                <span>Yeh summary AI ne students ke reviews se banai hai, is mein ghalti ho sakti hai. Poori baat ke liye neeche reviews parhein.</span>
            </p>
        </section>
    );
};

export default AiSummary;
